{
  "table": {
    "name": "California SAT results by school and district",
    "purpose": "SAT test results for California grade-12 students, one row per school (rtype='S') or school district (rtype='D'), keyed by the 14-digit CDS code. For each record it reports grade-12 enrollment, the number of SAT takers, the average score for each of the three sections (Reading, Math, Writing, each on the 200-800 scale of the pre-2016 SAT with a 2400-point total), and the number of test takers whose total score was at least 1500. Score fields are null where results are not reported (records with zero or very few test takers). School-level rows link to the schools table via cds -> schools.CDSCode; county, district and school names are denormalized onto each row. The presence of a Writing section and a 1500-of-2400 threshold dates the data to the 2005-early 2016 SAT administration era."
  },
  "columns": {
    "AvgScrMath": {
      "role": "numeric",
      "name": "Average SAT Math score",
      "description": "Mean SAT Math section score of the record's grade-12 test takers, on the 200-800 section scale (observed 289-699, mean ~484). Null in 26.3% of rows - the same rows as the other score columns, where results are not reported because there were zero or very few test takers (e.g. a row with NumTstTakr=3 has null scores).",
      "status": "resolved"
    },
    "AvgScrRead": {
      "role": "numeric",
      "name": "Average SAT Reading (Critical Reading) score",
      "description": "Mean SAT Critical Reading section score of the record's grade-12 test takers, on the 200-800 scale (observed 308-653, mean ~480). Null in 26.3% of rows where results are not reported (see AvgScrMath).",
      "status": "resolved"
    },
    "AvgScrWrite": {
      "role": "numeric",
      "name": "Average SAT Writing score",
      "description": "Mean SAT Writing section score of the record's grade-12 test takers, on the 200-800 scale (observed 312-671, mean ~473). The existence of a separate Writing section indicates the pre-2016 three-section SAT (total 2400). Null in 26.3% of rows where results are not reported (see AvgScrMath).",
      "status": "resolved"
    },
    "NumGE1500": {
      "role": "numeric",
      "name": "Number of test takers scoring 1500 or above",
      "description": "Count of the record's SAT test takers whose total score (Reading + Math + Writing, maximum 2400) was 1500 or greater (observed 0-5837). Null on the same 26.3% of rows where the score averages are not reported.",
      "status": "resolved"
    },
    "NumTstTakr": {
      "role": "numeric",
      "name": "Number of SAT test takers",
      "description": "Number of grade-12 students at the school (rtype='S') or district (rtype='D') who took the SAT (observed 0-24305; 218 records report 0 test takers, and records with no or very few takers have null score averages). Always populated.",
      "status": "resolved"
    },
    "cds": {
      "role": "identifier",
      "name": "CDS code (County-District-School identifier)",
      "description": "14-digit California County-District-School code: 2-digit county code + 5-digit district code + 7-digit school code. District-level rows (rtype='D') carry the district code with the school portion zeroed (e.g. 19650520000000 = county 19 Los Angeles, district 65252 Temple City Unified; 37683383734431 = San Diego county, San Diego Unified, Mission Bay High). Unique across all 2269 rows, so it identifies the row even though not flagged as the primary key. References schools.CDSCode (one-to-one). Stored as text and should be treated as an identifier, not a number (leading zeros are possible).",
      "status": "resolved"
    },
    "cname": {
      "role": "category",
      "name": "County name",
      "description": "Name of the California county of the school/district (e.g. Los Angeles, San Diego, Merced, Lassen); 57 distinct values, matching California's 58 counties. Repeated because each county contains many schools and districts.",
      "status": "resolved"
    },
    "dname": {
      "role": "category",
      "name": "District name",
      "description": "Name of the school district or county office of education (e.g. 'Los Angeles Unified', 'Kern High', 'Nevada County Office of Education'). Repeated across rows: each district appears once as its own rtype='D' aggregate row and once per school (rtype='S') within it.",
      "status": "resolved"
    },
    "enroll12": {
      "role": "numeric",
      "name": "Grade 12 enrollment",
      "description": "Number of students enrolled in grade 12 at the school (rtype='S') or in the whole district (rtype='D'); observed 0-43324, with the largest values corresponding to big districts such as Los Angeles Unified.",
      "status": "resolved"
    },
    "rtype": {
      "role": "code",
      "name": "Record type (school vs. district)",
      "description": "Level of the row: 'S' = school-level record (1749 rows; sname populated, cds has a non-zero 7-digit school portion), 'D' = district-level aggregate (520 rows; sname null, cds ends in 0000000).",
      "status": "resolved"
    },
    "sname": {
      "role": "category",
      "name": "School name",
      "description": "Name of the school (e.g. 'Mission Bay High'). Null exactly on the district-level rows (rtype='D', 520 of 2269 = 23%). Not unique - common names such as 'Middle College High' or 'Foothill High' occur in several different districts.",
      "status": "resolved"
    }
  }
}
